fn summarize_overview(histories: Vec<MemberHistory>) -> crate::domain::models::entity_details::CommonsOverview {
    use crate::domain::models::entity_details::{CommonsOverview, OverviewMember, OverviewParty, OverviewQuartile};
    let year = CalendarYear::containing(chrono::Utc::now());
    let mut parties: BTreeMap<i32, OverviewParty> = BTreeMap::new();
    let member_count = histories.len();
    let mut incomplete = false;
    let mut known = Vec::new();
    for history in histories {
        let details = summarize_member(history, year);
        let total = details.summary.declared_totals.current_term;
        incomplete |= total.incomplete;
        let party = parties.entry(details.member.party_id).or_insert_with(|| OverviewParty {
            party_id: details.member.party_id,
            party_name: details.member.party_name.clone(),
            total: DeclaredGbpPeriodTotal { amount: None, declaration_count: 0, incomplete: false },
            member_count: 0,
        });
        party.member_count += 1;
        party.total.declaration_count += total.declaration_count;
        party.total.incomplete |= total.incomplete;
        add_known(&mut party.total.amount, total.amount.as_ref());
        if total.amount.is_some() {
            known.push(OverviewMember { member: details.member, total });
        }
    }
    known.sort_by(|a, b| a.total.amount.cmp(&b.total.amount).then_with(|| a.member.id.value().cmp(&b.member.id.value())));
    let quartiles = (0..4).map(|index| {
        let group = &known[index * known.len() / 4..(index + 1) * known.len() / 4];
        OverviewQuartile {
            quartile: index + 1,
            member_count: group.len(),
            minimum: group.first().and_then(|member| member.total.amount.clone()),
            maximum: group.last().and_then(|member| member.total.amount.clone()),
            incomplete_member_count: group.iter().filter(|member| member.total.incomplete).count(),
        }
    }).collect();
    let unavailable_member_count = member_count - known.len();
    known.sort_by(|a, b| b.total.amount.cmp(&a.total.amount).then_with(|| a.member.id.value().cmp(&b.member.id.value())));
    known.truncate(5);
    CommonsOverview { current_term_start: CurrentParliamentStart::new().0, member_count, unavailable_member_count, incomplete, quartiles, top_members: known, parties: parties.into_values().collect() }
}
